SELECT (DATE_TRUNC('DAY', "GRANTED_AT")) AS "TIME_BUCKET", SUM(CASE WHEN ROLE_NAME IN ('ACCOUNTADMIN', 'SECURITYADMIN', 'ORGADMIN') AND REVOKED_AT IS NULL THEN 1 ELSE 0 END) AS "SEC_PRIVILEGED_GRANTS" FROM (SELECT g."ROLE" AS ROLE_NAME, g."GRANTED_TO" AS GRANTED_TO, g."GRANTEE_NAME" AS GRANTEE_NAME, g."GRANTED_BY" AS GRANTED_BY, (TRY_CAST(g."CREATED_ON" AS TIMESTAMP)) AS GRANTED_AT, (TRY_CAST(g."DELETED_ON" AS TIMESTAMP)) AS REVOKED_AT, COALESCE(u."DISABLED", FALSE) AS GRANTEE_DISABLED, u."TYPE" AS GRANTEE_TYPE, (TRY_CAST(u."LAST_SUCCESS_LOGIN" AS TIMESTAMP)) AS GRANTEE_LAST_LOGIN_AT FROM grants_to_users AS g LEFT JOIN users AS u ON u."NAME" = g."GRANTEE_NAME") AS base GROUP BY (DATE_TRUNC('DAY', "GRANTED_AT")) ORDER BY "SEC_PRIVILEGED_GRANTS" DESC, "TIME_BUCKET" LIMIT 100
